package org.hermesmobile.app

import kotlinx.serialization.json.*
import org.hermesmobile.app.data.*
import org.junit.Assert.*
import org.junit.Test

class CustomEndpointTest {
    private val owner=ManagementTarget("a".repeat(64),"https://host.test/prefix/","worker","password · fixture")
    private val id="Local.Example:8443"
    private val url="https://endpoint.test/private?key=url-private-fixture"
    private fun j(text:String)=Json.parseToJsonElement(text).jsonObject
    private fun raw()=buildJsonObject {put("providers",buildJsonObject {put(id,buildJsonObject {put("api_key","existing-inline-fixture");put("extra_headers",buildJsonObject {put("private","header-private-fixture")})});put("hidden",buildJsonObject {put("key_env","HIDDEN_REF")})});put("custom_providers",JsonArray(emptyList()));put("unrelated","not-retained-fixture")}
    private fun row(id:String=this.id,source:String="providers")=buildJsonObject {put("id",id);put("name","Private endpoint fixture");put("base_url",url);put("model","private-model");put("models",JsonArray(listOf(JsonPrimitive("private-model"))));put("api_mode","anthropic_messages");put("context_length",4096);put("discover_models",true);put("has_api_key",true);put("api_key_preview","preview-private-fixture");put("is_current",false);put("source",source)}
    private fun metadata(rows:List<JsonObject> = listOf(row()))=buildJsonObject {put("endpoints",JsonArray(rows));put("current",buildJsonObject {put("provider","openrouter");put("model","old-model");put("base_url","https://primary.test/v1")})}
    private fun snapshot(meta:JsonObject=metadata(),config:JsonObject=raw())=CustomEndpointSnapshot.parse(meta,config,owner,"home-fixture")
    private fun draft(id:String=this.id,key:CustomEndpointKey=CustomEndpointKey.Keep,secret:String="")=CustomEndpointDraft(id,"Private endpoint fixture",url,"private-model",key,secret)
    @Test fun existingLiteralCaseDotsAndColonArePreservedAndKeepOmitsCredentialAndMode() {val s=snapshot();val req=CustomEndpointRequest.save(s,draft(),s.rows.single());assertEquals(setOf("id","name","base_url","model","discover_models","make_default"),req.draft!!.body().keys);assertEquals(id,req.draft.body().text("id"));assertTrue(s.canAddress(s.rows.single()));assertFalse(req.draft.body().containsKey("profile"));assertFalse(req.draft.body().containsKey("context_length"))}
    @Test fun freshAndExplicitClearAreDifferentFromOmission() {val fresh=draft(key=CustomEndpointKey.Fresh,secret="  fresh-endpoint-fixture  ");assertEquals("fresh-endpoint-fixture",fresh.body().text("api_key"));assertEquals(JsonPrimitive(""),draft(key=CustomEndpointKey.Clear).body()["api_key"]);assertFalse(draft().body().containsKey("api_key"))}
    @Test fun optionalCanonicalModeContextModelAddsAndDefaultAreExact() {val d=CustomEndpointDraft("new-id"," Name ","https://new.test/v1/"," model ",apiMode="",contextLength=8192,discoverModels=false,makeDefault=true,models=listOf("other-model"));assertEquals("https://new.test/v1",d.baseUrl);assertEquals(JsonPrimitive(""),d.body()["api_mode"]);assertEquals(JsonPrimitive(8192),d.body()["context_length"]);assertEquals(JsonPrimitive(true),d.body()["make_default"]);assertEquals(JsonPrimitive(false),d.body()["discover_models"]);assertEquals(JsonArray(listOf(JsonPrimitive("other-model"))),d.body()["models"]);assertFalse(d.body().containsKey("model_details"))}
    @Test fun hiddenProviderCollisionCannotBeOverwrittenByCreation() {val s=snapshot();assertFalse(s.freshId("hidden"));assertTrue(runCatching {CustomEndpointRequest.save(s,draft("hidden"))}.exceptionOrNull() is CustomEndpointDuplicate)}
    @Test fun trimmedSavedProviderKeyAlsoBlocksNewId() {val config=raw().toMutableMap();config["providers"]=buildJsonObject {put(" new-id ",buildJsonObject {put("key_env","PRIVATE")})};val s=snapshot(metadata(emptyList()),JsonObject(config));assertFalse(s.freshId("new-id"));assertTrue(runCatching {CustomEndpointRequest.save(s,draft("new-id"))}.exceptionOrNull() is CustomEndpointDuplicate)}
    @Test fun newIdsMatchVerifiedSlugRulesWithoutSilentNormalization() {assertEquals("local-endpoint-8443",CustomEndpointPolicy.slug(" Local.Endpoint:8443 "));assertEquals("custom",CustomEndpointPolicy.slug("你好"));assertTrue(CustomEndpointPolicy.newId("new_id-2"));for(v in listOf("Mixed.Case","new_","_new","new/id","..")) assertFalse(v,CustomEndpointPolicy.newId(v));val s=snapshot();assertTrue(runCatching {CustomEndpointRequest.save(s,draft("Mixed.Case"))}.isFailure)}
    @Test fun legacySelectorNeedsOneUnambiguousNameAndNoHiddenProviderCollision() {val entry=buildJsonObject {put("name","Legacy Name");put("api_key","legacy-inline-fixture")};val config=buildJsonObject {put("custom_providers",JsonArray(listOf(entry)))};val s=snapshot(metadata(listOf(row("legacy-name","custom_providers"))),config);assertTrue(s.canAddress(s.rows.single()));val duplicate=snapshot(metadata(listOf(row("legacy-name","custom_providers"))),buildJsonObject {put("custom_providers",JsonArray(listOf(entry,entry)))});assertFalse(duplicate.canAddress(duplicate.rows.single()));val hidden=snapshot(metadata(listOf(row("legacy-name","custom_providers"))),buildJsonObject {put("providers",buildJsonObject {put("legacy-name",JsonObject(emptyMap()))});put("custom_providers",JsonArray(listOf(entry)))});assertFalse(hidden.canAddress(hidden.rows.single()))}
    @Test fun ambiguousLegacyNameShapeDisablesCreationRatherThanGuessingPythonCoercion() {val s=snapshot(metadata(emptyList()),buildJsonObject {put("custom_providers",buildJsonArray {add(buildJsonObject {put("name",17)})})});assertFalse(s.canCreate);assertTrue(runCatching {CustomEndpointRequest.save(s,draft("new-id"))}.exceptionOrNull() is CustomEndpointUnavailable)}
    @Test fun syntheticInlineMainRouteAndUnknownSourcesHaveNoMutatingControls() {for(source in listOf("direct-config","future-source")) {val s=snapshot(metadata(listOf(row("custom",source))));assertFalse(s.canAddress(s.rows.single()));assertTrue(runCatching {CustomEndpointRequest.remove(s,s.rows.single())}.isFailure);assertTrue(runCatching {CustomEndpointRequest.activate(s,s.rows.single())}.isFailure)}}
    @Test fun rowsCannotBeSubstitutedAcrossSnapshotsOrProfiles() {val a=snapshot();val b=snapshot();assertTrue(runCatching {CustomEndpointRequest.save(a,draft(),b.rows.single())}.isFailure);val other=CustomEndpointSnapshot.parse(metadata(),raw(),owner.copy(profile="other"),"other-home");assertTrue(runCatching {CustomEndpointRequest.remove(a,other.rows.single())}.isFailure)}
    @Test fun privateProviderChangesInvalidateButPreviewAndUnrelatedChangesDoNot() {val a=snapshot();assertFalse(a.same(snapshot(config=j(raw().toString().replace("header-private-fixture","rotated-header")))));assertFalse(a.same(snapshot(config=j(raw().toString().replace("existing-inline-fixture","rotated-inline")))));assertTrue(a.same(snapshot(meta=j(metadata().toString().replace("preview-private-fixture","different-preview")),config=j(raw().toString().replace("not-retained-fixture","different-unrelated"))))) }
    @Test fun secretPreviewsAndPrivateBodiesNeverAppearInReceiptSummariesOrToString() {val s=snapshot();val d=draft(key=CustomEndpointKey.Fresh,secret="fresh-endpoint-fixture");val req=CustomEndpointRequest.save(s,d,s.rows.single());val ack=req.acknowledge(buildJsonObject {put("ok",true);put("id",id);put("endpoints","private-optional-error")});for(v in listOf(s,s.rows.single(),s.current,d,req,ack)) for(secret in listOf(id,url,"private-model","existing-inline-fixture","header-private-fixture","fresh-endpoint-fixture","preview-private-fixture")) assertFalse(v.toString().contains(secret));for(secret in listOf(id,url,"private-model","fresh-endpoint-fixture")) assertFalse(req.summary().toString().contains(secret));assertFalse(ack.summary.toString().contains("private-optional-error"))}
    @Test fun malformedOptionalReplyInventoryCannotEraseTypedSaveAcknowledgment() {val s=snapshot();val req=CustomEndpointRequest.save(s,draft(),s.rows.single());val ack=req.acknowledge(j("""{"ok":true,"id":"normalized-id","endpoints":17,"current":"private-error"}"""));assertEquals("normalized-id",ack.id);assertEquals(JsonPrimitive(false),ack.summary["reported_id_matches_requested"])}
    @Test fun activateAcknowledgmentCanReportNormalizationWithoutPretendingItMatched() {val s=snapshot();val ack=CustomEndpointRequest.activate(s,s.rows.single()).acknowledge(j("""{"ok":true,"provider":"normalized-provider","model":"normalized-model"}"""));assertEquals(JsonPrimitive(false),ack.summary["reported_route_matches_requested"]);assertFalse(ack.summary.toString().contains("normalized-provider"))}
    @Test fun mandatorySuccessAndActionFieldsAreStrictlyTyped() {val s=snapshot();for(action in CustomEndpointAction.entries) {val req=when(action) {CustomEndpointAction.Save->CustomEndpointRequest.save(s,draft(),s.rows.single());CustomEndpointAction.Activate->CustomEndpointRequest.activate(s,s.rows.single());CustomEndpointAction.Remove->CustomEndpointRequest.remove(s,s.rows.single())};for(raw in listOf("{}","{\"ok\":\"true\"}","{\"ok\":false}")) assertTrue(runCatching {req.acknowledge(j(raw))}.isFailure)};assertTrue(runCatching {CustomEndpointRequest.activate(s,s.rows.single()).acknowledge(j("""{"ok":true,"provider":"p"}"""))}.isFailure)}
    @Test fun sharedGeneratedEnvironmentNamesAreDetectedWithoutPersistingNames() {assertEquals("HERMES_CUSTOM_LOCAL_EXAMPLE_8443_API_KEY",CustomEndpointPolicy.keySlot(id));assertEquals(CustomEndpointPolicy.keySlot("a.b"),CustomEndpointPolicy.keySlot("a-b"));val s=snapshot(config=buildJsonObject {put("providers",buildJsonObject {put("a.b",JsonObject(emptyMap()))})});assertTrue(s.sharesGeneratedKey("a-b"));val summary=CustomEndpointRequest.save(s,draft("a-b")).summary();assertEquals(JsonPrimitive(true),summary["known_shared_key_slot"]);assertFalse(summary.toString().contains("a.b"))}
    @Test fun freshKeysRejectMasksReferencesAndControls() {for(key in listOf("***","********","abcd...wxyz","${'$'}{PRIVATE_ENV}","prefix-${'$'}{PRIVATE_ENV}","bad\nkey")) assertTrue(key,runCatching {draft(key=CustomEndpointKey.Fresh,secret=key)}.isFailure);assertTrue(CustomEndpointPolicy.freshKey("fresh-credential-fixture"))}
    @Test fun boundsAndUnsupportedRootShapesRefuseWithoutTruncation() {for(config in listOf("{\"providers\":17}","{\"custom_providers\":{}}")) assertTrue(runCatching {snapshot(config=j(config))}.exceptionOrNull() is CustomEndpointUnavailable);assertTrue(runCatching {snapshot(metadata(List(201) {row("id-$it")}))}.exceptionOrNull() is CustomEndpointUnavailable);assertTrue(runCatching {CustomEndpointDraft("new-id","name","file:///tmp/key","model")}.isFailure);assertTrue(runCatching {CustomEndpointDraft("new-id","name",url,"model",contextLength=0)}.isFailure);assertTrue(runCatching {CustomEndpointDraft("new-id","name",url,"model",apiMode="unknown")}.isFailure)}
    @Test fun duplicateCatalogIdsAndStringBooleansRefuseWholeSnapshot() {assertTrue(runCatching {snapshot(metadata(listOf(row(),row())))}.isFailure);val bad=JsonObject(row()+mapOf("has_api_key" to JsonPrimitive("true")));assertTrue(runCatching {snapshot(metadata(listOf(bad)))}.isFailure)}
    @Test fun literalBodyOnlyIdsCanBeEditedWithoutInventingPathMutations() {
        for(id in listOf("Team/Model?%entry",".","..","Endpoint#Fragment")) {
            val raw=buildJsonObject {put("providers",buildJsonObject {put(id,JsonObject(emptyMap()))})};val snapshot=snapshot(metadata(listOf(row(id))),raw);val row=snapshot.rows.single()
            assertTrue(snapshot.canEdit(row));assertFalse(snapshot.canAddress(row));assertEquals(id,CustomEndpointRequest.save(snapshot,draft(id),row).draft!!.body().text("id"));assertTrue(runCatching {CustomEndpointRequest.remove(snapshot,row)}.isFailure);assertTrue(runCatching {CustomEndpointRequest.activate(snapshot,row)}.isFailure)
        }
    }
    @Test fun inputCollectionsAndSnapshotListsCannotChangeFrozenBodies() {val models=mutableListOf("additional");val d=CustomEndpointDraft("new-id","name",url,"model",models=models);models.clear();assertEquals(listOf("additional"),d.models);assertTrue(runCatching {(d.models as MutableList).clear()}.isFailure);val s=snapshot();assertTrue(runCatching {(s.rows as MutableList).clear()}.isFailure);assertTrue(runCatching {(s.rows.single().models as MutableList).clear()}.isFailure)}
}
